UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-357","language":"English","title":"Oviducts","topic_slug":"oviducts","definition":"The oviducts (fallopian tubes) are about 10-12 cm long and extend from the periphery of each ovary to the uterus. The part closer to the ovary is the funnel-shaped infundibulum, which has finger-like projections called fimbriae that help collect the ovum after ovulation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'oviducts' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-358","language":"English","title":"Female External Genitalia","topic_slug":"female-external-genitalia","definition":"The female external genitalia include mons pubis, labia majora, labia minora, hymen, and clitoris. Mons pubis is a cushion of fatty tissue covered by skin and pubic hair, while the labia majora are fleshy folds of tissue that surround the vaginal opening.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'female-external-genitalia' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-359","language":"English","title":"Mammary Glands","topic_slug":"mammary-glands","definition":"A functional mammary gland is characteristic of all female mammals, with the mammary glands being paired structures (breasts) that contain glandular tissue and variable amounts of fat. The glandular tissue of each breast is divided into 15-20 mammary lobes containing clusters of cells called alveoli that secrete milk.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mammary-glands' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-360","language":"English","title":"Spermatogenesis","topic_slug":"spermatogenesis","definition":"Spermatogonia multiply by mitotic division and increase in numbers, with each spermatogonium being diploid and containing 46 chromosomes. Some of the spermatogonia called primary spermatocytes periodically undergo meiosis, leading to the formation of two equal, haploid cells called secondary spermatocytes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'spermatogenesis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-361","language":"English","title":"Oogenesis","topic_slug":"oogenesis","definition":"Oogenesis is the process by which a mature female gamete is formed, which is markedly different from spermatogenesis. Oogenesis is initiated during the embryonic development stage when a couple of million gamete mother cells (oogonia) are formed within each fetal ovary.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'oogenesis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-362","language":"English","title":"Structure of Sperm","topic_slug":"structure-of-sperm","definition":"A sperm is a microscopic structure composed of a head, neck, a middle piece, and a tail, with a plasma membrane enveloping the whole body of the sperm. The sperm head contains an elongated haploid nucleus, the anterior portion of which is covered by a cap-like structure called the acrosome.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-sperm' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-363","language":"English","title":"Fertilisation","topic_slug":"fertilisation","definition":"Fertilisation is the process by which a sperm fuses with an ovum to form a zygote, which is essential for the continuation of the species. The acrosome of the sperm helps in the fertilisation of the ovum by releasing enzymes that break down the outer layer of the ovum.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fertilisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-364","language":"English","title":"Microbes in Household Products","topic_slug":"microbes-in-household-products","definition":"Microbes like bacteria and many fungi can be grown on nutritive media to form colonies, which can be seen with the naked eyes. Such cultures are useful in studies on micro-organisms. Examples of microbes used in household products include Lactobacillus and other lactic acid bacteria (LAB) used in the production of curd from milk. LAB produce acids that coagulate and partially digest the milk proteins, improving the nutritional quality of the curd by increasing vitamin B12. LAB also play a beneficial role in checking disease-causing microbes in the stomach.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'microbes-in-household-products' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-365","language":"English","title":"Microbes in Industrial Products","topic_slug":"microbes-in-industrial-products","definition":"Microbes are used to synthesise a number of products valuable to human beings, including beverages and antibiotics. Fermented beverages like wine, beer, whisky, brandy, and rum are produced using the yeast Saccharomyces cerevisiae. This yeast is used for fermenting malted cereals and fruit juices to produce ethanol. Depending on the type of raw material used and the type of processing, different types of alcoholic drinks are obtained. Wine and beer are produced without distillation, while whisky, brandy, and rum are produced by distillation of the fermented broth.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'microbes-in-industrial-products' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-366","language":"English","title":"Antibiotics","topic_slug":"antibiotics","definition":"Antibiotics produced by microbes are regarded as one of the most significant discoveries of the twentieth century. Antibiotics are chemical substances produced by some microbes that can kill or retard the growth of other (disease-causing) microbes. Penicillin was the first antibiotic to be discovered, and it was a chance discovery by Alexander Fleming. Fleming observed a mould growing in one of his unwashed culture plates around which Staphylococci could not grow. He found out that it was due to a chemical produced by the mould and named it Penicillin after the mould Penicillium notatum.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'antibiotics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-367","language":"English","title":"Chemicals, Enzymes, and other Bioactive Molecules","topic_slug":"chemicals-enzymes-and-other-bioactive-molecules","definition":"Microbes are used for commercial and industrial production of certain chemicals like organic acids, alcohols, and enzymes. Examples of acid producers include Aspergillus niger (a fungus) of citric acid, Acetobacter aceti (a bacterium) of acetic acid, and Clostridium butylicum (a bacterium) of butyric acid. Yeast (Saccharomyces cerevisiae) is used for commercial production of ethanol. Microbes are also used for production of enzymes, including lipases, pectinases, and proteases. Streptokinase produced by the bacterium Streptococcus and modified by genetic engineering is used as a ''clot buster'' for removing clots from the blood vessels of patients who have undergone myocardial infarction leading to heart attack.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'chemicals-enzymes-and-other-bioactive-molecules' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-368","language":"English","title":"Microbes in Sewage Treatment","topic_slug":"microbes-in-sewage-treatment","definition":"Large quantities of waste water are generated every day in cities and towns, and a major component of this waste water is human excreta. This municipal waste-water is also called sewage and contains large amounts of organic matter and microbes, many of which are pathogenic. Sewage is treated in sewage treatment plants (STPs) to make it less polluting. Treatment of waste water is done by the heterotrophic microbes naturally present in the sewage. The treatment is carried out in two stages: primary treatment and secondary treatment or biological treatment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'microbes-in-sewage-treatment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-369","language":"English","title":"Primary Treatment","topic_slug":"primary-treatment","definition":"Primary treatment involves physical removal of particles – large and small – from the sewage through filtration and sedimentation. The treatment steps basically involve sequential filtration to remove floating debris and sedimentation to remove grit (soil and small pebbles). All solids that settle form the primary sludge, and the supernatant forms the effluent. The effluent from the primary settling tank is taken for secondary treatment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'primary-treatment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-370","language":"English","title":"Secondary Treatment or Biological Treatment","topic_slug":"secondary-treatment-or-biological-treatment","definition":"The primary effluent is passed into large aeration tanks where it is constantly agitated mechanically and air is pumped into it. This allows vigorous growth of useful aerobic microbes into flocs (masses of bacteria associated with fungal filaments to form mesh-like structures). While growing, these microbes consume the major part of the organic matter in the effluent, significantly reducing the BOD (biochemical oxygen demand) of the effluent. The BOD test measures the rate of uptake of oxygen by micro-organisms in a sample of water and thus, indirectly, BOD is a measure of the organic matter present in the water.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'secondary-treatment-or-biological-treatment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3df-en-371","language":"English","title":"Biogas Production","topic_slug":"biogas-production","definition":"Once the BOD of sewage or waste water is reduced significantly, the effluent is then passed into a settling tank where the bacterial ''flocs'' are allowed to sediment. This sediment is called activated sludge, and a small part of it is pumped back into the aeration tank to serve as the inoculum. The remaining major part of the sludge is pumped into large tanks called anaerobic sludge digesters. In these digesters, other kinds of bacteria, which grow anaerobically, digest the bacteria and the fungi in the sludge, producing a mixture of gases such as methane, hydrogen sulphide, and carbon dioxide. These gases form biogas and can be used as a source of energy as it is inflammable.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3df' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'biogas-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3db-en-372","language":"English","title":"Structure of Polynucleotide Chains","topic_slug":"structure-of-polynucleotide-chains","definition":"A polynucleotide chain is a long chain of nucleotides, each consisting of a sugar molecule (ribose in RNA and deoxyribose in DNA), a phosphate group, and a nitrogenous base. The sugar and phosphate molecules form the backbone of the polynucleotide chain, while the nitrogenous bases project from the backbone. The 5''-end of the polynucleotide chain has a free phosphate group, and the 3''-end has a free 3''-OH group.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3db' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-polynucleotide-chains' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3db-en-373","language":"English","title":"Discovery of DNA","topic_slug":"discovery-of-dna","definition":"DNA was first identified as an acidic substance present in the nucleus by Friedrich Meischer in 1869. He named it as ‘Nuclein’. Due to technical limitations in isolating a long polymer intact, the elucidation of DNA structure remained elusive for a long period of time.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3db' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'discovery-of-dna' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3db-en-374","language":"English","title":"Structure of DNA","topic_slug":"structure-of-dna","definition":"James Watson and Francis Crick proposed a Double Helix model for the structure of DNA in 1953. The Double Helix model was based on the X-ray diffraction data produced by Maurice Wilkins and Rosalind Franklin. The model proposed base pairing between the two strands of polynucleotide chains.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3db' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-dna' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3db-en-375","language":"English","title":"Base Pairing in DNA","topic_slug":"base-pairing-in-dna","definition":"The base pairing in DNA confers a unique property to the polynucleotide chains. They are said to be complementary to each other, and therefore if the sequence of bases in one strand is known, the sequence in the other strand can be predicted. If each strand from a DNA acts as a template for synthesis of a new strand, the two double-stranded DNA produced would be identical to the parental DNA molecule.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3db' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'base-pairing-in-dna' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3db-en-376","language":"English","title":"Salient Features of Double-Helix Structure of DNA","topic_slug":"salient-features-of-double-helix-structure-of-dna","definition":"The Double-helix structure of DNA is made of two polynucleotide chains, where the backbone is constituted by sugar-phosphate, and the bases project inside. The two chains have anti-parallel polarity, meaning if one chain has the polarity 5''→3'', the other has 3''→5''. The bases in two strands are paired through hydrogen bond (H-bonds) forming base pairs (bp). Adenine forms two hydrogen bonds with Thymine from the opposite strand and vice-versa. Guanine is bonded with Cytosine with three H-bonds. As a result, always a purine comes opposite to a pyrimidine. This generates approximately uniform distance between the two strands of the helix.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3db' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'salient-features-of-double-helix-structure-of-dna' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-377","language":"English","title":"Inheritance of One Gene","topic_slug":"inheritance-of-one-gene","definition":"Inheritance of one gene refers to the study of how a single gene is passed down from one generation to the next. Mendel conducted an experiment to study the inheritance of one gene by crossing tall and dwarf pea plants. He observed that all the F1 progeny plants were tall, like one of its parents, and none were dwarf.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'inheritance-of-one-gene' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-378","language":"English","title":"Monohybrid Cross","topic_slug":"monohybrid-cross","definition":"A monohybrid cross is a cross between two parents that differ in one pair of contrasting traits. In a monohybrid cross, the F1 generation always resembles one of the parents, and the trait of the other parent is not seen in them. Mendel self-pollinated the tall F1 plants and found that in the F2 generation, some of the offspring were ''dwarf'', while 3/4th of the F2 plants were tall.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'monohybrid-cross' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-379","language":"English","title":"Genotype and Phenotype","topic_slug":"genotype-and-phenotype","definition":"Genotype refers to the genetic makeup of an organism, while phenotype refers to the physical expression of the genotype. In the case of the character of height, the pair of alleles for height would be TT, Tt, or tt. The genotype of a plant is represented by the pair of alleles, while the phenotype is represented by the descriptive terms tall and dwarf.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'genotype-and-phenotype' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-380","language":"English","title":"Dominance and Recessiveness","topic_slug":"dominance-and-recessiveness","definition":"In a pair of dissimilar factors, one dominates the other and is called the dominant factor, while the other factor is recessive. In the case of the character of height, T (for tallness) is dominant over t (for dwarfness). The concept of dominance and recessiveness can be remembered by using the capital and lower case of an alphabetical symbol.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dominance-and-recessiveness' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-381","language":"English","title":"Punnett Square","topic_slug":"punnett-square","definition":"A Punnett square is a graphical representation to calculate the probability of all possible genotypes of offspring in a genetic cross. The Punnett square shows the parental tall TT (male) and dwarf tt (female) plants, the gametes produced by them, and the F1 Tt progeny. The F1 plant of the genotype Tt when self-pollinated, produces gametes of the genotype T and t in equal proportion.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'punnett-square' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-382","language":"English","title":"Test Cross","topic_slug":"test-cross","definition":"A test cross is a cross between an organism showing a dominant phenotype and the recessive parent. The progenies of a test cross can easily be analysed to predict the genotype of the test organism. Mendel proposed two general rules to consolidate his understanding of inheritance in monohybrid crosses: the First Law or Law of Dominance and the Second Law or Law of Segregation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'test-cross' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-383","language":"English","title":"Law of Dominance","topic_slug":"law-of-dominance","definition":"The Law of Dominance states that characters are controlled by discrete units called factors. Factors occur in pairs, and in a dissimilar pair of factors, one member of the pair dominates the other. The Law of Dominance explains the expression of only one of the parental characters in a monohybrid cross in the F1 and the expression of both in the F2.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'law-of-dominance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3da-en-384","language":"English","title":"Incomplete Dominance","topic_slug":"incomplete-dominance","definition":"Incomplete dominance occurs when the F1 has a phenotype that does not resemble either of the two parents and is in between the two. The inheritance of flower colour in the dog flower (snapdragon or Antirrhinum sp.) is a good example to understand incomplete dominance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3da' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'incomplete-dominance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-385","language":"English","title":"Reproduction in Organisms","topic_slug":"reproduction-in-organisms","definition":"Reproduction is a biological process in which an organism gives rise to young ones (offspring) similar to itself. The offspring grow, mature, and in turn produce new offspring, resulting in a cycle of birth, growth, and death. Reproduction enables the continuity of the species, generation after generation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'reproduction-in-organisms' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-386","language":"English","title":"Types of Reproduction","topic_slug":"types-of-reproduction","definition":"Reproduction can be of two types based on the participation of one or two organisms in the process. Asexual reproduction involves the production of offspring by a single parent with or without the involvement of gamete formation. Sexual reproduction involves the participation of two parents (opposite sex) and the fusion of male and female gametes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-reproduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-387","language":"English","title":"Asexual Reproduction","topic_slug":"asexual-reproduction","definition":"Asexual reproduction is a method in which a single individual (parent) is capable of producing offspring. The offspring produced are not only identical to one another but are also exact copies of their parent. The term clone is used to describe such morphologically and genetically similar individuals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'asexual-reproduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-388","language":"English","title":"Mechanisms of Asexual Reproduction","topic_slug":"mechanisms-of-asexual-reproduction","definition":"Asexual reproduction is common among single-celled organisms, and in plants and animals with relatively simple organisations. In Protists and Monerans, the organism or the parent cell divides into two to give rise to new individuals. Many single-celled organisms reproduce by binary fission, where a cell divides into two halves and each rapidly grows into an adult.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mechanisms-of-asexual-reproduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-389","language":"English","title":"Asexual Reproductive Structures","topic_slug":"asexual-reproductive-structures","definition":"Members of the Kingdom Fungi and simple plants such as algae reproduce through special asexual reproductive structures. The most common of these structures are zoospores that usually are microscopic motile structures. Other common asexual reproductive structures are conidia (Penicillium), buds (Hydra), and gemmules (sponge).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'asexual-reproductive-structures' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d6-en-390","language":"English","title":"Advantages of Asexual Reproduction","topic_slug":"advantages-of-asexual-reproduction","definition":"Asexual reproduction is the common method of reproduction in organisms that have a relatively simple organisation, like algae and fungi. It is also the method of reproduction in organisms that shift to sexual method of reproduction just before the onset of adverse conditions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'advantages-of-asexual-reproduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-391","language":"English","title":"Reproductive Health","topic_slug":"reproductive-health","definition":"Reproductive health refers to healthy reproductive organs with normal functions, including emotional and social aspects of reproduction. According to the World Health Organisation (WHO), reproductive health means a total well-being in all aspects of reproduction, i.e., physical, emotional, behavioural and social. A society with people having physically and functionally normal reproductive organs and normal emotional and behavioural interactions among them in all sex-related aspects might be called reproductively healthy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'reproductive-health' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-392","language":"English","title":"Reproductive Health – Problems and Strategies","topic_slug":"reproductive-health-problems-and-strategies","definition":"India was amongst the first countries in the world to initiate action plans and programmes at a national level to attain total reproductive health as a social goal. These programmes called ‘family planning’ were initiated in 1951 and were periodically assessed over the past decades. Improved programmes covering decreased maternal and infant mortality rates, increased number of couples with small families, better detection and cure of STDs and overall increased medical facilities for all sex-related problems, etc. all indicate improved reproductive health of the society.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'reproductive-health-problems-and-strategies' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-393","language":"English","title":"Population Explosion and Birth Control","topic_slug":"population-explosion-and-birth-control","definition":"In the last century, an all-round development in various fields significantly improved the quality of life of the people. However, increased health facilities along with better living conditions had an explosive impact on the growth of population. The world population which was around 2 billion (2000 million) in 1900 rocketed to about 6 billions by 2000. A similar trend was observed in India too, with our population which was approximately 350 million at the time of our independence reaching close to the billion mark by 2000 and crossing 1 billion in May 2000.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'population-explosion-and-birth-control' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-394","language":"English","title":"Methods of Birth Control","topic_slug":"methods-of-birth-control","definition":"The most important step to overcome the problem of population explosion is to motivate smaller families by using various contraceptive methods. An ideal contraceptive should be user-friendly, easily available, effective and reversible with no or least side-effects. It also should in no way interfere with the sexual drive, desire and/or the sexual act of the user. A wide range of contraceptive methods are presently available which could be broadly grouped into the following categories, namely Natural/Traditional, Barrier, IUDs, Oral contraceptives, Injectables, Implants and Surgical methods.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'methods-of-birth-control' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-395","language":"English","title":"Natural/Traditional Methods","topic_slug":"natural-traditional-methods","definition":"Natural methods work on the principle of avoiding chances of ovum and sperms meeting. Periodic abstinence is one such method in which the couples avoid or abstain from coitus from day 10 to 17 of the menstrual cycle. It is one of the most widely accepted methods of contraception in India.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'natural-traditional-methods' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-396","language":"English","title":"Barrier Methods","topic_slug":"barrier-methods","definition":"Oral administration of small doses of either progestogens or progestogen–estrogen combinations is another contraceptive method used by the females. They are used in the form of tablets and hence are popularly called the pills. Pills have to be taken daily for a period of 21 days starting preferably within the first five days of menstrual cycle. After a gap of 7 days (during which menstruation occurs) it has to be repeated in the same pattern till the female desires to prevent conception.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'barrier-methods' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-397","language":"English","title":"IUDs, Injectables, Implants, and Surgical Methods","topic_slug":"iuds-injectables-implants-and-surgical-methods","definition":"Progestogens alone or in combination with estrogen can also be used by females as injections or implants under the skin. Their mode of action is similar to that of pills and their effective periods are much longer. Administration of progestogens or progestogen-estrogen combinations or IUDs within 72 hours of coitus have been found to be very effective as emergency contraceptives. Surgical methods, also called sterilisation, are generally advised for the male/female partner as a terminal method to prevent any more pregnancies.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'iuds-injectables-implants-and-surgical-methods' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-398","language":"English","title":"Sexually Transmitted Diseases","topic_slug":"sexually-transmitted-diseases","definition":"Diseases or infections which are transmitted through sexual intercourse are collectively called sexually transmitted diseases (STD) or venereal diseases (VD) or reproductive tract infections (RTI). Gonorrhoea, syphilis, genital herpes, chlamydiasis, genital warts, trichomoniasis, hepatitis-B and of course, the most discussed infection in the recent years, HIV leading to AIDS are some of the common STDs. Among these, HIV infection is most dangerous and is discussed in detail in Chapter 8.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'sexually-transmitted-diseases' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-399","language":"English","title":"Prevention of STDS","topic_slug":"prevention-of-stds","definition":"Prevention or early detection and cure of these diseases are given prime consideration under the reproductive health-care programmes. Though all persons are vulnerable to these infections, their incidences are reported to be very high among persons in the age group of 15-24 years – the age group to which you also belong. Don’t panic. Prevention is in your hands. You could be free of these infections if you follow the simple principles given below: Avoid sex with unknown partners/multiple partners. Always use condoms during coitus. In case of doubt, go to a qualified doctor for early detection and get complete treatment if diagnosed with disease.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'prevention-of-stds' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d9-en-400","language":"English","title":"Infertility","topic_slug":"infertility","definition":"A discussion on reproductive health is incomplete without a mention of infertility. A large number of couples all over the world including India are infertile, i.e., they are unable to produce children inspite of unprotected sexual co-habitation. The reasons for this could be many– physical, congenital, diseases, drugs, immunological or even psychological.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'infertility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-401","language":"English","title":"2.1 Stamen, Microsporangium and Pollen Grain","topic_slug":"2-1-stamen-microsporangium-and-pollen-grain","definition":"A stamen is the male reproductive part of a flower, consisting of a long and slender stalk called the filament and a terminal structure called the anther. The anther is generally bilobed with each lobe having two theca, making it dithecous. A typical angiosperm anther is a four-sided (tetragonal) structure consisting of four microsporangia located at the corners, two in each lobe.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = '2-1-stamen-microsporangium-and-pollen-grain' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-402","language":"English","title":"Structure of Microsporangium","topic_slug":"structure-of-microsporangium","definition":"A microsporangium is a small, near-circular structure surrounded by four wall layers: the epidermis, endothecium, middle layers, and the tapetum. The outer three wall layers perform the function of protection and help in dehiscence of the anther to release the pollen. The innermost wall layer is the tapetum, which nourishes the developing pollen grains.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-microsporangium' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-403","language":"English","title":"Microsporogenesis","topic_slug":"microsporogenesis","definition":"Microsporogenesis is the process of formation of microspores from a pollen mother cell through meiosis. The cells of the sporogenous tissue undergo meiotic divisions to form microspore tetrads. Each cell of the sporogenous tissue is capable of giving rise to a microspore tetrad, making each one a potential pollen or microspore mother cell (PMC).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'microsporogenesis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-404","language":"English","title":"Pollen Grain","topic_slug":"pollen-grain","definition":"A pollen grain represents the male gametophyte and is generally spherical, measuring about 25-50 micrometers in diameter. It has a prominent two-layered wall, with the hard outer layer called the exine made up of sporopollenin. The exine exhibits a fascinating array of patterns and designs, and the inner wall of the pollen grain is called the intine, made up of cellulose and pectin.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'pollen-grain' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-405","language":"English","title":"2.2 The Pistil, Megasporangium (Ovule) and Embryo sac","topic_slug":"2-2-the-pistil-megasporangium-ovule-and-embryo-sac","definition":"The gynoecium represents the female reproductive part of the flower and may consist of a single pistil (monocarpellary) or more than one pistil (multicarpellary). Each pistil has three parts: the stigma, style, and ovary, with the stigma serving as a landing platform for pollen grains.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = '2-2-the-pistil-megasporangium-ovule-and-embryo-sac' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-406","language":"English","title":"Structure of the Ovule","topic_slug":"structure-of-the-ovule","definition":"An ovule is a small structure attached to the placenta by means of a stalk called the funicle. The body of the ovule fuses with the funicle in the region called the hilum. Each ovule has one or two protective envelopes called integuments, which encircle the ovule except at the tip where a small opening called the micropyle is organised.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-the-ovule' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d7-en-407","language":"English","title":"Types of Pollination","topic_slug":"types-of-pollination","definition":"There are two main types of pollination: self-pollination and cross-pollination. Self-pollination occurs when pollen grains are transferred from the anther to the stigma of the same flower, while cross-pollination occurs when pollen grains are transferred from the anther of one flower to the stigma of another flower.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-pollination' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-408","language":"English","title":"Strategies for Enhancement in Food Production","topic_slug":"strategies-for-enhancement-in-food-production","definition":"Poultry farming requires proper management, including selection of disease-free and suitable breeds, proper and safe farm conditions, proper feed and water, and hygiene and health care. The ''bird flu virus'' created a scare in the country and drastically affected egg and chicken consumption, highlighting the need for strategies to prevent the spread of diseases in poultry farming.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'strategies-for-enhancement-in-food-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-409","language":"English","title":"Animal Breeding","topic_slug":"animal-breeding","definition":"Animal breeding aims at increasing the yield of animals and improving the desirable qualities of the produce. Breeding for desirable characters would include traits such as increased milk production, improved egg quality, and faster growth rates. The selection of characters would differ with the choice of animals, as different breeds have different characteristics.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'animal-breeding' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-410","language":"English","title":"Breeds and Breeding","topic_slug":"breeds-and-breeding","definition":"A breed is a group of animals related by descent and similar in most characters, such as general appearance, features, size, and configuration. Common breeds of cattle and poultry in farms include Jersey, Leghorn, and Bikaneri ewes. Breeding between animals of the same breed is called inbreeding, while breeding between different breeds is called outbreeding.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'breeds-and-breeding' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-411","language":"English","title":"Inbreeding and Outbreeding","topic_slug":"inbreeding-and-outbreeding","definition":"Inbreeding refers to the mating of more closely related individuals within the same breed for 4-6 generations. Inbreeding increases homozygosity and exposes harmful recessive genes, which are eliminated by selection. Out-breeding is the breeding of unrelated animals, which may be between individuals of the same breed but having no common ancestors for 4-6 generations or between different breeds.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'inbreeding-and-outbreeding' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-412","language":"English","title":"Cross-Breeding and Interspecific Hybridisation","topic_slug":"cross-breeding-and-interspecific-hybridisation","definition":"Cross-breeding involves mating superior males of one breed with superior females of another breed. Interspecific hybridisation involves mating male and female animals of two different related species. The progeny of interspecific hybridisation may combine desirable features of both parents and be of considerable economic value.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cross-breeding-and-interspecific-hybridisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-413","language":"English","title":"Artificial Insemination and Multiple Ovulation Embryo Transfer Technology","topic_slug":"artificial-insemination-and-multiple-ovulation-embryo-transfer-technology","definition":"Artificial insemination involves collecting semen from a male and injecting it into the reproductive tract of a female. MOET involves administering hormones to induce follicular maturation and super ovulation, resulting in the production of 6-8 eggs. The fertilised eggs are recovered and transferred to surrogate mothers, allowing for the rapid improvement of herd size.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'artificial-insemination-and-multiple-ovulation-embryo-transfer-technology' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-414","language":"English","title":"Bee-Keeping","topic_slug":"bee-keeping","definition":"Bee-keeping or apiculture involves the maintenance of hives of honeybees for the production of honey. Honey is a food of high nutritive value and also finds use in indigenous systems of medicine. Bee-keeping can be practiced in any area with sufficient bee pastures and requires some specialised knowledge.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bee-keeping' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-415","language":"English","title":"Bee-Keeping Practices","topic_slug":"bee-keeping-practices","definition":"Important points for successful bee-keeping include knowledge of the nature and habits of bees, selection of suitable locations, catching and hiving of swarms, management of beehives during different seasons, and handling and collection of honey and beeswax. Keeping beehives in crop fields during flowering periods increases pollination efficiency and improves crop yield and honey yield.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bee-keeping-practices' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-416","language":"English","title":"Fisheries","topic_slug":"fisheries","definition":"Fishery is an industry devoted to the catching, processing, or selling of fish, shellfish, or other aquatic animals. A large number of the population depends on fish, fish products, and other aquatic animals for food. Fisheries has an important place in the Indian economy, providing income and employment to millions of fishermen and farmers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fisheries' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-417","language":"English","title":"Plant Breeding","topic_slug":"plant-breeding","definition":"Plant breeding is the purposeful manipulation of plant species to create desired plant types that are better suited for cultivation, give better yields, and are disease resistant. Classical plant breeding involves crossing or hybridisation of pure lines, followed by artificial selection to produce plants with desirable traits.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'plant-breeding' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3de-en-418","language":"English","title":"Plant Breeding Programmes","topic_slug":"plant-breeding-programmes","definition":"Plant breeding programmes are carried out in a systematic way worldwide, in government institutions and commercial companies. The main steps in breeding a new genetic variety of a crop include collection of variability, evaluation of characteristics, and selection of desirable traits. Plant breeding has helped increase yields to a very large extent, and has been responsible for the Green Revolution in India.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3de' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'plant-breeding-programmes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-419","language":"English","title":"Developmental Path - A Snapshot View","topic_slug":"developmental-path-a-snapshot-view","definition":"The primary objective of this book, Indian Economic Development, is to familiarise the reader with the basic features of the Indian economy and its development, as it is today, in the aftermath of Independence. The structure of India''s present-day economy is not just of current making' || char(59) || ' it has its roots steeped in history, particularly in the period when India was under British rule which lasted for almost two centuries before India finally won its independence on 15 August 1947. The sole purpose of the British colonial rule in India was to reduce the country to being a raw material supplier for Great Britain''s own rapidly expanding modern industrial base.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'developmental-path-a-snapshot-view' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-420","language":"English","title":"Demographic Indicators","topic_slug":"demographic-indicators","definition":"India had an independent economy before the advent of the British rule. Though agriculture was the main source of livelihood for most people, yet, the country''s economy was characterised by various kinds of manufacturing activities. India was particularly well known for its handicraft industries in the fields of cotton and silk textiles, metal and precious stone works etc.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'demographic-indicators' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-421","language":"English","title":"Gross Domestic Product and Sectors","topic_slug":"gross-domestic-product-and-sectors","definition":"India''s economy under the British colonial rule remained fundamentally agrarian — about 85 per cent of the country''s population lived mostly in villages and derived livelihood directly or indirectly from agriculture. Despite being the occupation of such a large population, the agricultural sector continued to experience stagnation and, not infrequently, unusual deterioration. Agricultural productivity became low though, in absolute terms, the sector experienced some growth due to the expansion of the aggregate area under cultivation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'gross-domestic-product-and-sectors' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-422","language":"English","title":"Indicators of Human Development","topic_slug":"indicators-of-human-development","definition":"The economic policies pursued by the colonial government in India were concerned more with the protection and promotion of the economic interests of their home country than with the development of the Indian economy. Such policies brought about a fundamental change in the structure of the Indian economy — transforming the country into a supplier of raw materials and consumer of finished industrial products from Britain. The colonial government never made any sincere attempt to estimate India''s national and per capita income.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'indicators-of-human-development' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-423","language":"English","title":"Development Strategies - An Appraisal","topic_slug":"development-strategies-an-appraisal","definition":"The primary motive of the colonial government behind the policy of systematically de-industrialising India was two-fold. The intention was, first, to reduce India to the status of a mere exporter of important raw materials for the upcoming modern industries in Britain and, second, to turn India into a sprawling market for the finished products of those industries so that their continued expansion could be ensured to the maximum advantage of their home country — Britain. In the unfolding economic scenario, the decline of the indigenous handicraft industries created not only massive unemployment but also a huge gap in the country''s industrial base.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'development-strategies-an-appraisal' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-424","language":"English","title":"Indian Economy on the Eve of Independence","topic_slug":"indian-economy-on-the-eve-of-independence","definition":"The economic policies pursued by the colonial government in India were concerned more with the protection and promotion of the economic interests of their home country than with the development of the Indian economy. Such policies brought about a fundamental change in the structure of the Indian economy — transforming the country into a supplier of raw materials and consumer of finished industrial products from Britain. The colonial government never made any sincere attempt to estimate India''s national and per capita income.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'indian-economy-on-the-eve-of-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-425","language":"English","title":"Agricultural Sector","topic_slug":"agricultural-sector","definition":"India''s economy under the British colonial rule remained fundamentally agrarian — about 85 per cent of the country''s population lived mostly in villages and derived livelihood directly or indirectly from agriculture. Despite being the occupation of such a large population, the agricultural sector continued to experience stagnation and, not infrequently, unusual deterioration. Agricultural productivity became low though, in absolute terms, the sector experienced some growth due to the expansion of the aggregate area under cultivation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'agricultural-sector' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-426","language":"English","title":"Industrial Sector","topic_slug":"industrial-sector","definition":"As in the case of agriculture, so also in manufacturing, India could not develop a sound industrial base under the colonial rule. Even as the country''s world famous handicraft industries declined, no corresponding modern industrial base was allowed to come up to take pride of place so long enjoyed by the former. The primary motive of the colonial government behind this policy of systematically de-industrialising India was two-fold.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'industrial-sector' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-427","language":"English","title":"Development Policies and Experience","topic_slug":"development-policies-and-experience","definition":"The two chapters in this unit give us an overview of the state of the Indian economy as it was at the eve of independence till after four decades of planned development, which was a path that India chose. This meant that the Government of India had to take a series of steps such as the establishment of the Planning Commission and announcement of five year plans. An overview of the goals of five year plans and a critical appraisal of the merits and limitations of planned development has been covered in this unit.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'development-policies-and-experience' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de415-en-428","language":"English","title":"Fundamental Duties","topic_slug":"fundamental-duties","definition":"It shall be the duty of every citizen of India to abide by the Constitution and respect its ideals and institutions, the National Flag and the National Anthem. To cherish and follow the noble ideals which inspired our national struggle for freedom. To uphold and protect the sovereignty, unity and integrity of India.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de415' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fundamental-duties' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-429","language":"English","title":"Government Budget and the Economy","topic_slug":"government-budget-and-the-economy","definition":"The government budget is a plan for government spending and taxation for a specific period. It is a tool for implementing fiscal policy, which is a key component of macroeconomic policy. The government budget can be used to stabilize the economy, promote economic growth, and reduce unemployment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'government-budget-and-the-economy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-430","language":"English","title":"Government Spending Multiplier","topic_slug":"government-spending-multiplier","definition":"The government spending multiplier is a measure of the change in aggregate demand that results from a change in government spending. It is derived as follows: Suppose G changes to a new level (G+AG) and as a result Y changes to a new level (Y'' +AY). The new levels of G and Y can also be put into equation (5.4), which is: Y = C + TR + I + G. Substituting the new values of G and Y into this equation, we get: Y'' + AY = T(Cch+cTR+I+G+AG). Subtracting equation (5.4) from equation (5.4a), we get: AY = 7/5G. This can be rewritten as: AY = 1/2.6T%G.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'government-spending-multiplier' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-431","language":"English","title":"Changes in Taxes","topic_slug":"changes-in-taxes","definition":"A cut in taxes increases disposable income (Y - T) at each level of income. This shifts the aggregate expenditure schedule upwards by a fraction ¢ of the decrease in taxes. The tax multiplier is given by: AY = ¢ (AY - AT). This can be rewritten as: AY = ¢ (1 - ¢) AT.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'changes-in-taxes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-432","language":"English","title":"Tax Multiplier","topic_slug":"tax-multiplier","definition":"The tax multiplier is a negative multiplier, meaning that a tax cut will cause an increase in consumption and output. The tax multiplier is smaller in absolute value compared to the government spending multiplier. This is because an increase in government spending directly affects total spending, whereas taxes enter the multiplier process through their impact on disposable income.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'tax-multiplier' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-433","language":"English","title":"Balanced Budget Multiplier","topic_slug":"balanced-budget-multiplier","definition":"A balanced budget multiplier of unity implies that a 100 increase in G financed by a 100 increase in taxes increases income by just 100. This can be seen from Example 1, where an increase in G by 100 increases output by 500, and a tax increase would reduce income by 400, resulting in a net increase of 100. The balanced budget multiplier is 1 because the increase in government spending raises income directly, and the tax increase only enters the multiplier process when the cut in disposable income reduces consumption.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'balanced-budget-multiplier' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-434","language":"English","title":"Case of Proportional Taxes","topic_slug":"case-of-proportional-taxes","definition":"A more realistic assumption would be that the government collects a constant fraction, t, of income in the form of taxes, so that T = tY. The consumption function with proportional taxes is given by: c = C + cY - tY + TR. Proportional taxes not only lower consumption at each level of income but also lower the slope of the consumption function.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'case-of-proportional-taxes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-435","language":"English","title":"Increase in Government Expenditure","topic_slug":"increase-in-government-expenditure","definition":"An increase in government spending will cause an increase in consumption, but by less than the increase in income. The multiplier will now be given by: AY = AG + c(1 - t)AY. This can be rewritten as: AY = t(1 - t)AG.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'increase-in-government-expenditure' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-436","language":"English","title":"Automatic Stabilisers","topic_slug":"automatic-stabilisers","definition":"Proportional taxes act as an automatic stabiliser, making disposable income and consumer spending less sensitive to fluctuations in GDP. During a recession, disposable income falls less sharply, and consumption does not drop as much as it otherwise would have fallen. This reduces the fall in aggregate demand and stabilises the economy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'automatic-stabilisers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-437","language":"English","title":"Transfers","topic_slug":"transfers","definition":"Transfers refer to government payments to individuals or businesses, such as welfare payments or subsidies. The change in equilibrium income for a change in transfers is given by: AY = cATR. This can be rewritten as: AY = ¢ (1 - ¢) ATR.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'transfers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-438","language":"English","title":"Debt","topic_slug":"debt","definition":"Budgetary deficits must be financed by either taxation, borrowing, or printing money. Governments have mostly relied on borrowing, giving rise to what is called government debt. The concepts of deficits and debt are closely related, with deficits adding to the stock of debt.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'debt' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de410-en-439","language":"English","title":"Perspectives on the Appropriate Amount of Government Debt","topic_slug":"perspectives-on-the-appropriate-amount-of-government-debt","definition":"There are two interlinked aspects of the issue: whether government debt is a burden and the issue of financing the debt. The burden of debt must be discussed keeping in mind that what is true of one small trader''s debt may not be true for the government''s debt.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de410' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'perspectives-on-the-appropriate-amount-of-government-debt' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de3f5-en-440","language":"English","title":"Board Alignment","topic_slug":"board-alignment","definition":"This chapter is part of the official AHSEC HS 2nd Year History syllabus and is assessed in the Higher Secondary annual examination. Related: Kings, Farmers and Towns — Early States and Economies Related: Colonialism and the Countryside Related: Mahatma Gandhi and the Nationalist Movement","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de3f5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'board-alignment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c2-en-441","language":"English","title":"The Harappan Civilization: An Introduction","topic_slug":"the-harappan-civilization-an-introduction","definition":"The Indus Valley Civilization, also known as the Harappan culture, is named after Harappa, the first site where it was discovered. This civilization flourished between c. 2600 BCE and 1900 BCE, a period also referred to as the Mature Harappan culture. Its geographical spread was extensive, covering regions from Afghanistan and Jammu in the north to Baluchistan (Pakistan) and Gujarat in the west. The culture is distinguished by a group of objects, including seals, beads, weights, and baked bricks, found together in a specific area and time period.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-harappan-civilization-an-introduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c2-en-442","language":"English","title":"Archaeological Evidence and Key Artifacts","topic_slug":"archaeological-evidence-and-key-artifacts","definition":"Knowledge of the Harappan people is derived entirely from archaeological evidence such as houses, pottery, ornaments, tools, and seals. The most distinctive artifact is the steatite seal, which often features animal motifs and signs from an undeciphered script. Other significant finds include beads, weights, stone blades, and standardized baked bricks used in construction. Archaeologists use these distinctive objects to define and study the culture, interpreting how they were used in daily life.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'archaeological-evidence-and-key-artifacts' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c2-en-443","language":"English","title":"Subsistence and Agricultural Practices","topic_slug":"subsistence-and-agricultural-practices","definition":"The Harappan diet was diverse, consisting of wheat, barley, lentils, chickpeas, sesame, and millets, with rice being relatively rare. Animal remains include bones from domesticated cattle, sheep, goats, buffalo, and pigs, indicating a pastoral component to their economy. Agriculture was a primary activity, with evidence suggesting the use of oxen for ploughing, as indicated by terracotta models and seal representations. Irrigation was likely necessary for farming in semi-arid regions, with evidence of canals at sites like Shortughai and water reservoirs at Dholavira.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'subsistence-and-agricultural-practices' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c2-en-444","language":"English","title":"Phases of the Harappan Culture","topic_slug":"phases-of-the-harappan-culture","definition":"The Harappan civilization is divided into three main phases: Early Harappan, Mature Harappan, and Late Harappan. There was a distinct break between the Early and Mature phases, marked by large-scale burning at some sites and the abandonment of certain settlements. The Mature Harappan phase saw the development of large urban centers and extensive trade networks, building upon earlier cultural foundations. The Late Harappan phase followed the decline of the Mature phase, representing a transition to a more rural and de-urbanized culture. Topic 1: ~60 words Topic 2: ~60 words Topic 3: ~70 words Topic 4: ~75 words Total: ~265 words.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'phases-of-the-harappan-culture' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de3f6-en-445","language":"English","title":"Board Alignment","topic_slug":"board-alignment","definition":"This chapter is part of the official AHSEC HS 2nd Year History syllabus and is assessed in the Higher Secondary annual examination. Related: Bricks, Beads and Bones — The Harappan Civilisation Related: Kinship, Caste and Class — Early Societies Related: Colonial Cities — Urbanisation Planning and Architecture","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de3f6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'board-alignment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-446","language":"English","title":"Challenges of Nation Building","topic_slug":"challenges-of-nation-building","definition":"A democratic constitution is necessary but not sufficient for establishing a democracy. The challenge was to develop democratic practices in accordance with the Constitution. The Constitution clearly laid down the principle of equality and special protection to socially disadvantaged groups and religious and cultural communities. The real challenge now was to evolve effective policies for economic development and eradication of poverty.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'challenges-of-nation-building' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-447","language":"English","title":"The First Challenge: Nation Building","topic_slug":"the-first-challenge-nation-building","definition":"The first challenge of nation-building occupied centre-stage in the years immediately after Independence. The issue of national unity and security became a primary challenge at the time of Independence. The unity had to reflect the aspirations of people across different regions and deal with the disparities that existed among regions and different sections of people.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-first-challenge-nation-building' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-448","language":"English","title":"The Context of Independence","topic_slug":"the-context-of-independence","definition":"The events that formed the context of Independence helped us understand why the issue of national unity and security became a primary challenge at the time of Independence. The partition of British India into India and Pakistan was a result of the division of the border demarcating the territory of each country. The drawing of the border was the culmination of political developments that had been read about in history textbooks.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-context-of-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-449","language":"English","title":"The Two-Nation Theory","topic_slug":"the-two-nation-theory","definition":"The Muslim League advanced the ''two-nation theory'', which stated that India consisted of not one but two ''people'', Hindus and Muslims. This theory demanded Pakistan, a separate country for the Muslims. The Congress opposed this theory and the demand for Pakistan.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-two-nation-theory' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-450","language":"English","title":"The Process of Partition","topic_slug":"the-process-of-partition","definition":"The division of British India into India and Pakistan was not only very painful but also very difficult to decide and to implement. The principle of religious majorities was followed, which meant that areas where the Muslims were in majority would make up the territory of Pakistan. The rest was to stay with India.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-process-of-partition' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-451","language":"English","title":"The Consequences of Partition","topic_slug":"the-consequences-of-partition","definition":"The year 1947 was the year of one of the largest, most abrupt, unplanned, and tragic transfer of population that human history has known. There were killings and atrocities on both sides of the border. Cities like Lahore and Amritsar became divided into ''communal zones''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-consequences-of-partition' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-452","language":"English","title":"The Trauma of Partition","topic_slug":"the-trauma-of-partition","definition":"Minorities on both sides of the border fled their home and often secured temporary shelter in ''refugee camps''. They often found unhelpful local administration and police in what was till recently their own country. Thousands of women were abducted on both sides of the border and were made to convert to the religion of the abductor and were forced into marriage.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-trauma-of-partition' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de404-en-453","language":"English","title":"The Legacy of Partition","topic_slug":"the-legacy-of-partition","definition":"The partition was described as a ''division of hearts'' by writers, poets, and film-makers in India and Pakistan. The trauma of Partition was recounted in novels, short-stories, poems, and films. The survivors themselves used the phrase to describe partition, highlighting the ruthlessness of the killings and the suffering of displacement and violence.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de404' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-legacy-of-partition' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-454","language":"English","title":"Challenges to the Congress System","topic_slug":"challenges-to-the-congress-system","definition":"The Congress party faced significant challenges in 1967 due to the economic crisis in the country, including a decline in agricultural production, serious food shortage, depletion of foreign exchange reserves, drop in industrial production and exports, combined with a sharp rise in military expenditure and diversion of resources from planning and economic development. The economic situation triggered off price rise, leading to widespread protests against the increase in prices of essential commodities, food scarcity, growing unemployment, and the overall economic condition in the country. The government saw the protests as a law and order problem and not as expressions of people''s problems, further increasing public bitterness and reinforcing popular unrest.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'challenges-to-the-congress-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-455","language":"English","title":"Non-Congressism","topic_slug":"non-congressism","definition":"The opposition parties realised that the division of their votes kept the Congress in power, and thus parties that were entirely different and disparate in their programmes and ideology got together to form anti-Congress fronts in some states and entered into electoral adjustments of sharing seats in others. The socialist leader Ram Manohar Lohia gave this strategy the name of ''non-Congressism'' and produced a theoretical argument in its defence: Congress rule was undemocratic and opposed to the interests of ordinary poor people, therefore, the coming together of non-Congress parties was necessary for reclaiming democracy for the people.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'non-congressism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-456","language":"English","title":"Electoral Verdict","topic_slug":"electoral-verdict","definition":"The fourth general elections to the Lok Sabha and State Assemblies were held in February 1967, in the context of heightened popular discontent and the polarisation of political forces. The Congress was facing the electorate for the first time without Nehru, and the results jolted the Congress at both the national and state levels, with many contemporary political observers describing the election results as a ''political earthquake''. The Congress did manage to get a majority in the Lok Sabha, but with its lowest tally of seats and share of votes since 1952, and half the ministers in Indira Gandhi''s cabinet were defeated.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'electoral-verdict' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-457","language":"English","title":"State Level Politics","topic_slug":"state-level-politics","definition":"The Congress lost majority in as many as seven States, and in two other States defections prevented it from forming a government, with these nine States spread across the country – Punjab, Haryana, Uttar Pradesh, Madhya Pradesh, Bihar, West Bengal, Orissa, Madras, and Kerala. In Madras State (now called Tamil Nadu), a regional party – the Dravida Munnetra Kazhagam (DMK) – came to power by securing a clear majority, after having led a massive anti-Hindi agitation by students against the centre on the issue of imposition of Hindi as the official language.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'state-level-politics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-458","language":"English","title":"Coalitions","topic_slug":"coalitions","definition":"The elections of 1967 brought into picture the phenomenon of coalitions, with various non-Congress parties coming together to form joint legislative parties (called Samyukt Vidhayak Dal in Hindi) that supported non-Congress governments. In most of these cases the coalition partners were ideologically incongruent, with the SVD government in Bihar, for instance, including the two socialist parties – SSP and the PSP – along with the CPI on the left and Jana Sangh on the right.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'coalitions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-459","language":"English","title":"Restoration of the Congress System","topic_slug":"restoration-of-the-congress-system","definition":"The Congress party was able to restore its dominance in the country through a combination of factors, including the leadership of Indira Gandhi, who was able to consolidate power within the party and implement policies that addressed the economic and social challenges facing the country. The Congress party also implemented policies to address the concerns of the opposition parties, including the implementation of the 20-point programme, which aimed to address the economic and social challenges facing the country. The Congress party was also able to restore its dominance through the use of administrative and electoral machinery, including the use of government machinery to influence the outcome of elections and the use of administrative measures to suppress opposition.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'restoration-of-the-congress-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de408-en-460","language":"English","title":"Impact of the 1967 Elections","topic_slug":"impact-of-the-1967-elections","definition":"The 1967 elections had a significant impact on Indian politics, marking a shift away from the dominance of the Congress party and towards a more multiparty system. The elections also marked a shift towards coalition politics, with the formation of coalition governments in several states and the emergence of regional parties as major players in Indian politics. The elections also marked a shift towards a more decentralized system of government, with the emergence of regional parties and the decline of the Congress party''s dominance at the national level.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de408' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'impact-of-the-1967-elections' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-461","language":"English","title":"Crisis of Democratic Order","topic_slug":"crisis-of-democratic-order","definition":"The crisis of democratic order in India began with the Bihar movement led by Jayaprakash Narayan, which was a protest against the Bihar government. The movement was gaining national attention, and Jayaprakash Narayan wanted to spread it to other parts of the country. The movement was supported by non-Congress opposition parties like the Bharatiya Jana Sangh, the Congress (O), the Bharatiya Lok Dal, the Socialist Party, and others.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'crisis-of-democratic-order' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-462","language":"English","title":"Politics in India since Independence","topic_slug":"politics-in-india-since-independence","definition":"The opposition parties were projecting Jayaprakash Narayan as an alternative to Indira Gandhi. However, there were many criticisms about his ideas and the politics of mass agitations that he was employing. The Gujarat and Bihar agitations were seen as anti-Congress and rather than opposing the State governments, they were seen as protests against the leadership of Indira Gandhi.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-463","language":"English","title":"Railway Strike of 1974","topic_slug":"railway-strike-of-1974","definition":"The Railway Strike of 1974 was a nationwide strike by all employees of the Railways for pressing their demands related to bonus and service conditions. The strike was led by the National Coordination Committee for Railwaymen’s Struggle and was supported by George Fernandes. The strike added to the atmosphere of labour unrest and raised issues like the rights of workers and whether employees of essential services should adopt measures like strikes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'railway-strike-of-1974' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-464","language":"English","title":"Conflict with Judiciary","topic_slug":"conflict-with-judiciary","definition":"The government and the ruling party had many differences with the judiciary during this period. Three constitutional issues had emerged: Can the Parliament abridge Fundamental Rights? Can the Parliament curtail the right to property by making an amendment? The Supreme Court said that Parliament cannot abridge Fundamental Rights or curtail the right to property by making an amendment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'conflict-with-judiciary' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-465","language":"English","title":"Declaration of Emergency","topic_slug":"declaration-of-emergency","definition":"On 12 June 1975, Justice Jagmohan Lal Sinha of the Allahabad High Court passed a judgment declaring Indira Gandhi’s election to the Lok Sabha invalid. The judgment meant that legally she was no more an MP and therefore, could not remain the Prime Minister unless she was once again elected as an MP within six months. On June 24, the Supreme Court granted her a partial stay on the High Court order – till her appeal was decided, she could remain an MP but could not take part in the proceedings of the Lok Sabha.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'declaration-of-emergency' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-466","language":"English","title":"Crisis and Response","topic_slug":"crisis-and-response","definition":"The opposition political parties led by Jayaprakash Narayan pressed for Indira Gandhi’s resignation and organised a massive demonstration in Delhi’s Ramlila grounds on 25 June 1975. Jayaprakash announced a nationwide satyagraha for her resignation and asked the army, the police, and government employees not to obey “illegal and immoral orders”.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'crisis-and-response' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-467","language":"English","title":"Declaration of Emergency by Government","topic_slug":"declaration-of-emergency-by-government","definition":"The response of the government was to declare a state of emergency on 25 June 1975. The government declared that there was a threat of internal disturbances and therefore, it invoked Article 352 of the Constitution. Under the provision of this article, the government could declare a state of emergency on grounds of external threat or a threat of internal disturbances.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'declaration-of-emergency-by-government' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-468","language":"English","title":"Consequences of Emergency","topic_slug":"consequences-of-emergency","definition":"The declaration of emergency brought the agitation to an abrupt stop' || char(59) || ' strikes were banned' || char(59) || ' many opposition leaders were put in jail' || char(59) || ' the political situation became very quiet though tense. The government suspended the freedom of the Press, and newspapers were asked to get prior approval for all material to be published. Protests and strikes and public agitations were also disallowed, and the various Fundamental Rights of citizens stood suspended, including the right of citizens to move the Court for restoring their Fundamental Rights.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'consequences-of-emergency' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-469","language":"English","title":"Preventive Detention","topic_slug":"preventive-detention","definition":"The government made extensive use of preventive detention during the Emergency. Under this provision, people were arrested and detained not because they had committed any offence, but on the apprehension that they may commit an offence. Arrested political workers could not challenge their arrest through habeas corpus petitions, and several High Courts gave judgments that even after the declaration of Emergency, the courts could entertain a writ of habeas corpus filed by a person challenging his/her detention.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'preventive-detention' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de409-en-470","language":"English","title":"Resistance to Emergency","topic_slug":"resistance-to-emergency","definition":"There were many acts of dissent and resistance to the Emergency. Many political workers who were not arrested in the first wave, went ‘underground’ and organised protests against the government. Newspapers like the Indian Express and the Statesman protested against censorship by leaving blank spaces where news items had been censored.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de409' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'resistance-to-emergency' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-471","language":"English","title":"Politics of Planned Development","topic_slug":"politics-of-planned-development","definition":"The concept of planned development gained significant attention globally in the 1940s and 1950s, with the experience of the Great Depression, inter-war reconstruction of Japan and Germany, and the Soviet Union''s economic growth contributing to this consensus. The Planning Commission was established in March 1950 by a simple resolution of the Government of India, with an advisory role and recommendations becoming effective only when approved by the Union Cabinet. The Planning Commission''s scope of work was defined by the resolution, which stated that the State shall strive to promote the welfare of the people by securing and protecting a social order in which justice, social, economic, and political shall be ensured.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-of-planned-development' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-472","language":"English","title":"Planning Commission","topic_slug":"planning-commission","definition":"The Planning Commission was not a sudden invention, but rather a result of a joint proposal by a section of big industrialists in 1944, known as the Bombay Plan. The Bombay Plan advocated for the state to take major initiatives in industrial and other economic investments, marking a shift towards planning for development. The Prime Minister was the Chairperson of the Planning Commission, which became the most influential and central machinery for deciding India''s development path.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'planning-commission' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-473","language":"English","title":"The Early Initiatives","topic_slug":"the-early-initiatives","definition":"The Planning Commission opted for five-year plans (FYP), with the idea of preparing a document for all income and expenditure for the next five years. The budget of the central and state governments was divided into ''non-plan'' and ''plan'' budgets, with the ''plan'' budget spent on a five-year basis as per the priorities fixed by the plan. The First Five Year Plan (1951-1956) generated excitement in the country, with people from all walks of life discussing and debating the plan extensively.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-early-initiatives' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-474","language":"English","title":"The First Five Year Plan","topic_slug":"the-first-five-year-plan","definition":"The First Five Year Plan sought to get the country''s economy out of the cycle of poverty, with a focus on the agrarian sector, including investment in dams and irrigation. The plan identified the pattern of land distribution as the principal obstacle in the way of agricultural growth and focused on land reforms as the key to the country''s development. The plan aimed to raise the level of national income by pushing savings up, but the rise in savings was not as spectacular as expected.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-first-five-year-plan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-475","language":"English","title":"Rapid Industrialisation","topic_slug":"rapid-industrialisation","definition":"The Second FYP stressed on heavy industries, with a team of economists and planners under the leadership of P.C. Mahalanobis drafting the plan. The Second Plan wanted to bring about quick structural transformation by making changes simultaneously in all possible directions, with a focus on rapid industrialisation. The government imposed substantial tariffs on imports to protect domestic industries, leading to the growth of both public and private sector industries.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rapid-industrialisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-476","language":"English","title":"Politics in India since Independence","topic_slug":"politics-in-india-since-independence","definition":"The nationalist leaders were clear that the economic concerns of the government of free India would have to be different from the narrowly defined commercial functions of the colonial government. The task of poverty alleviation and social and economic redistribution was seen primarily as the responsibility of the government. There were debates among the nationalist leaders, with some prioritizing industrialisation and others focusing on the development of agriculture and alleviation of rural poverty.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3c8-en-477","language":"English","title":"Fast Forward","topic_slug":"fast-forward","definition":"The idea of planning as a process of rebuilding the economy earned a good deal of public support in the 1940s and 1950s. The experience of the Great Depression, inter-war reconstruction of Japan and Germany, and the Soviet Union''s economic growth contributed to this consensus. The Planning Commission was not a sudden invention, but rather a result of a joint proposal by a section of big industrialists in 1944, known as the Bombay Plan.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3c8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fast-forward' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-478","language":"English","title":"Era of One-Party Dominance","topic_slug":"era-of-one-party-dominance","definition":"The first general election in India was held from October 1951 to February 1952, and it took six months for the campaigning, polling, and counting to be completed. The election was competitive, with an average of more than four candidates for each seat, and the level of participation was encouraging, with more than half the eligible voters turning out to vote on the day of elections. The Indian experiment had proved the critics wrong, and the elections were accepted as fair even by the losers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'era-of-one-party-dominance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-479","language":"English","title":"Changing Methods of Voting","topic_slug":"changing-methods-of-voting","definition":"In the first general election, voters used a ballot paper with the election symbol of each candidate, and they had to drop the paper into the box of the candidate they wanted to vote for. The ballot paper was used from the third to the thirteenth general elections to Lok Sabha. The Electronic Voting Machine (EVM) was introduced after the first two elections, and by 2004, the entire country had shifted to the EVM.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'changing-methods-of-voting' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-480","language":"English","title":"Politics in India Since Independence","topic_slug":"politics-in-india-since-independence","definition":"The first general election was considered a big gamble in history, and some critics thought that universal adult franchise in India would be a failure. The election was postponed twice and finally held from October 1951 to February 1952. The results of the election were encouraging, with more than half the eligible voters turning out to vote on the day of elections.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-481","language":"English","title":"Congress Dominance in the First Three General Elections","topic_slug":"congress-dominance-in-the-first-three-general-elections","definition":"The Indian National Congress was expected to win the first general election, and it did so with a majority of seats in all the states except Travancore-Cochin, Madras, and Orissa. The Congress party had inherited the legacy of the national movement and had a strong organization spread all over the country. Jawaharlal Nehru, the leader of the Congress party, led the campaign and toured through the country.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'congress-dominance-in-the-first-three-general-elections' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-482","language":"English","title":"Electoral System and Congress Dominance","topic_slug":"electoral-system-and-congress-dominance","definition":"The electoral system used in India, known as the first-past-the-post method, tends to favor the party that gets more votes than others, giving them a disproportionate number of seats. In the first general election, the Congress party won 364 out of 489 seats, despite getting only 45% of the total votes. The Socialist Party, the second-largest party in terms of votes, secured more than 10% of the votes but could not win even 3% of the seats.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'electoral-system-and-congress-dominance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-483","language":"English","title":"Communist Victory in Kerala","topic_slug":"communist-victory-in-kerala","definition":"In the assembly elections held in March 1957, the Communist Party won the largest number of seats in the Kerala legislature, winning 60 out of 126 seats. The governor invited E.M.S. Namboodiripad, the leader of the Communist legislature party, to form the ministry, making it the first Communist party government to come to power through democratic elections.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'communist-victory-in-kerala' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de405-en-484","language":"English","title":"The Origins of the Socialist Party","topic_slug":"the-origins-of-the-socialist-party","definition":"The Socialist Party originated from the Congress Socialist Party (CSP), which was formed within the Indian National Congress in 1934 by a group of young leaders who wanted a more radical and egalitarian Congress. The Socialist Party believed in the ideology of democratic socialism, which distinguished them from the Congress and the Communists. The party faced a dilemma when the Congress declared its goal to be the socialist pattern of society, making it difficult for the socialists to present themselves as an effective alternative to the Congress.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de405' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-origins-of-the-socialist-party' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-485","language":"English","title":"International Context","topic_slug":"international-context","definition":"India was born in a very trying and challenging international context, with the world witnessing a devastating war and grappling with issues of reconstruction. Many new countries were emerging as a result of the collapse of colonialism, and most new nations were trying to come to terms with the twin challenges of welfare and democracy. Free India''s foreign policy reflected all these concerns in the period immediately after Independence, apart from the global factors, India had its own share of concerns, including the British government''s legacy of international disputes, the pressures of Partition, and the task of poverty alleviation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'international-context' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-486","language":"English","title":"Politics in India since Independence","topic_slug":"politics-in-india-since-independence","definition":"The Cold War was just beginning, and the world was getting divided into two camps, with India belonging to neither of them in global politics of the fifties and the sixties. India''s foreign policy was peaceful and avoided international conflicts, with the policy of non-alignment being a crucial aspect of its foreign policy. The Indian national movement was not an isolated process, but a part of the worldwide struggle against colonialism and imperialism, influencing the liberation movements of many Asian and African countries.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-487","language":"English","title":"The Policy of Non-Alignment","topic_slug":"the-policy-of-non-alignment","definition":"The foreign policy of a nation reflects the interplay of domestic and external factors, and India''s attainment of independence coincided with the beginning of the Cold War era. The policy of non-alignment was a difficult balancing act, and sometimes the balance did not appear perfect, as seen in India''s response to the Suez Canal issue and the Hungarian invasion. India advocated non-alignment as the ideal foreign policy approach, which was a test of its independence and sovereignty.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-policy-of-non-alignment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-488","language":"English","title":"Nehru''s Role","topic_slug":"nehru-s-role","definition":"Jawaharlal Nehru played a crucial role in setting the national agenda and exercising profound influence in the formulation and implementation of India''s foreign policy from 1946 to 1964. The three major objectives of Nehru''s foreign policy were to preserve the hard-earned sovereignty, protect territorial integrity, and promote rapid economic development. Nehru wished to achieve these objectives through the strategy of non-alignment, which was a difficult balancing act and sometimes the balance did not appear perfect.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'nehru-s-role' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-489","language":"English","title":"Distance from Two Camps","topic_slug":"distance-from-two-camps","definition":"India wanted to keep away from the military alliances led by the US and the Soviet Union against each other, and advocated non-alignment as the ideal foreign policy approach. This was a difficult balancing act, and sometimes the balance did not appear perfect, as seen in India''s response to the Suez Canal issue and the Hungarian invasion. India did take an independent stand on various international issues and could get aid and assistance from members of both the blocs.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'distance-from-two-camps' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-490","language":"English","title":"Afro-Asian Unity","topic_slug":"afro-asian-unity","definition":"Nehru envisaged a major role for India in world affairs and especially in Asian affairs, given its size, location, and power potential. His era was marked by the establishment of contacts between India and other newly independent states in Asia and Africa, and India made earnest efforts for the early realisation of freedom of Indonesia from the Dutch colonial regime. India was a staunch supporter of the decolonisation process and firmly opposed racism, especially apartheid in South Africa.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'afro-asian-unity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-491","language":"English","title":"Peace and Conflict with China","topic_slug":"peace-and-conflict-with-china","definition":"Unlike its relationship with Pakistan, free India began its relationship with China on a very friendly note, with India being one of the first countries to recognise the Chinese revolution in 1949. India''s relationship with China was marked by peace and cooperation, with India supporting China''s entry into the United Nations and China supporting India''s bid for a permanent seat in the UN Security Council. However, the Sino-Indian border dispute led to a conflict in 1962, which had a significant impact on India''s foreign policy and its relationship with China.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'peace-and-conflict-with-china' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de407-en-492","language":"English","title":"India''s Nuclear Policy","topic_slug":"india-s-nuclear-policy","definition":"India''s nuclear policy was shaped by its foreign policy and its relationship with other countries, with India being a strong advocate of nuclear disarmament and non-proliferation. India''s nuclear policy was also influenced by its desire to become a major world power and its need to protect its national security and sovereignty. India''s nuclear policy has undergone significant changes over the years, with India conducting nuclear tests in 1974 and 1998, and becoming a member of the Nuclear Suppliers Group in 2016.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de407' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'india-s-nuclear-policy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-493","language":"English","title":"Politics of Planned Development","topic_slug":"politics-of-planned-development","definition":"The concept of planned development gained significant attention globally in the 1940s and 1950s, with the experience of the Great Depression, inter-war reconstruction of Japan and Germany, and the Soviet Union''s economic growth contributing to this consensus. The Planning Commission was established in March 1950 by a simple resolution of the Government of India, with an advisory role and recommendations becoming effective only when approved by the Union Cabinet. The Planning Commission''s scope of work was defined by the resolution, which stated that the State shall strive to promote the welfare of the people by securing and protecting a social order in which justice, social, economic, and political shall be ensured.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-of-planned-development' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-494","language":"English","title":"Planning Commission","topic_slug":"planning-commission","definition":"The Planning Commission was not a sudden invention, but rather a result of a joint proposal by a section of big industrialists in 1944, known as the Bombay Plan. The Bombay Plan advocated for the state to take major initiatives in industrial and other economic investments, marking a shift towards planning for development. The Prime Minister was the Chairperson of the Planning Commission, which became the most influential and central machinery for deciding India''s development path.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'planning-commission' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-495","language":"English","title":"The Early Initiatives","topic_slug":"the-early-initiatives","definition":"The Planning Commission opted for five-year plans (FYP), with the idea of preparing a document for all income and expenditure for the next five years. The budget of the central and state governments was divided into ''non-plan'' and ''plan'' budgets, with the ''plan'' budget spent on a five-year basis as per the priorities fixed by the plan. The First Five Year Plan (1951-1956) generated excitement in the country, with people from all walks of life discussing and debating the plan extensively.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-early-initiatives' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-496","language":"English","title":"The First Five Year Plan","topic_slug":"the-first-five-year-plan","definition":"The First Five Year Plan sought to get the country''s economy out of the cycle of poverty, with a focus on the agrarian sector, including investment in dams and irrigation. The plan identified the pattern of land distribution as the principal obstacle in the way of agricultural growth and focused on land reforms as the key to the country''s development. The plan aimed to raise the level of national income by pushing savings up, but the rise in savings was not as spectacular as expected.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-first-five-year-plan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-497","language":"English","title":"Rapid Industrialisation","topic_slug":"rapid-industrialisation","definition":"The Second FYP stressed on heavy industries, with a team of economists and planners under the leadership of P.C. Mahalanobis drafting the plan. The Second Plan wanted to bring about quick structural transformation by making changes simultaneously in all possible directions, with a focus on rapid industrialisation. The government imposed substantial tariffs on imports to protect domestic industries, leading to the growth of both public and private sector industries.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rapid-industrialisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-498","language":"English","title":"Politics in India since Independence","topic_slug":"politics-in-india-since-independence","definition":"The nationalist leaders were clear that the economic concerns of the government of free India would have to be different from the narrowly defined commercial functions of the colonial government. The task of poverty alleviation and social and economic redistribution was seen primarily as the responsibility of the government. There were debates among the nationalist leaders, with some prioritizing industrialisation and others focusing on the development of agriculture and alleviation of rural poverty.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de406-en-499","language":"English","title":"Fast Forward","topic_slug":"fast-forward","definition":"The idea of planning as a process of rebuilding the economy earned a good deal of public support in the 1940s and 1950s. The experience of the Great Depression, inter-war reconstruction of Japan and Germany, and the Soviet Union''s economic growth contributed to this consensus. The Planning Commission was not a sudden invention, but rather a result of a joint proposal by a section of big industrialists in 1944, known as the Bombay Plan.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de406' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fast-forward' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-500","language":"English","title":"Recent Developments in Indian Politics","topic_slug":"recent-developments-in-indian-politics","definition":"The demolition of the disputed structure at Ayodhya (Babri Masjid) in December 1992 symbolised and triggered various changes in the country''s politics, intensifying debates about the nature of Indian nationalism and secularism. The event was associated with the rise of the BJP and the politics of ''Hindutva''. The assassination of Rajiv Gandhi in May 1991 led to a change in leadership of the Congress party, with Narsimha Rao being chosen as the Prime Minister.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'recent-developments-in-indian-politics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-501","language":"English","title":"Era of Coalitions","topic_slug":"era-of-coalitions","definition":"The elections of 1989 led to the defeat of the Congress party but did not result in a majority for any other party. The National Front (an alliance of Janata Dal and regional parties) received support from the BJP and the Left Front, forming a coalition government. The Congress party decided to sit in the opposition, marking the end of its dominance over the Indian party system.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'era-of-coalitions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-502","language":"English","title":"Decline of Congress","topic_slug":"decline-of-congress","definition":"The defeat of the Congress party in 1989 marked the end of its predominant position in politics. The nineties saw another challenge to the Congress''s position, but no single party emerged to replace it. The Congress party''s decline weakened its position, but it did not enable any single party to consolidate its position.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'decline-of-congress' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-503","language":"English","title":"Alliance Politics","topic_slug":"alliance-politics","definition":"The nineties saw the emergence of powerful parties and movements representing the Dalit and backward castes (OBCs). Many of these parties represented regional assertion and played a crucial role in the United Front government in 1996. The United Front government was supported by the Congress, showing the unstable nature of the political equations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'alliance-politics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-504","language":"English","title":"Coalition Governments","topic_slug":"coalition-governments","definition":"The era of coalition governments began in 1989, with eleven governments at the Centre being formed since then. These governments were either coalition governments or minority governments supported by other parties. Regional parties played a crucial role in forming ruling alliances, but this trend changed in 2014.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'coalition-governments' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-505","language":"English","title":"Rise of Other Backward Classes","topic_slug":"rise-of-other-backward-classes","definition":"The nineties saw the rise of the Other Backward Classes as a political force. The support for the Congress among many sections of the ''backward castes'' had declined, creating a space for non-Congress parties. The Janata Party government in 1977 was the first national-level expression of the rise of these parties.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rise-of-other-backward-classes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-506","language":"English","title":"Mandal Commission","topic_slug":"mandal-commission","definition":"The Mandal Commission was set up in 1978 to investigate the extent of educational and social backwardness among various sections of Indian society. The Commission recommended reserving 27 per cent of seats in educational institutions and government jobs for the backward castes. The implementation of the Mandal Commission report sparked off agitations and political upheavals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mandal-commission' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-507","language":"English","title":"Implementation of Mandal Commission Report","topic_slug":"implementation-of-mandal-commission-report","definition":"The National Front government decided to implement the Mandal Commission report in August 1990. The report recommended reserving 27 per cent of seats in educational institutions and government jobs for the backward castes. The implementation of the report helped in shaping the politics of the ''Other Backward Classes''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'implementation-of-mandal-commission-report' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40c-en-508","language":"English","title":"Politics of Coalition Governments","topic_slug":"politics-of-coalition-governments","definition":"The era of coalition governments may be seen as a long-term trend resulting from relatively silent changes over the last few decades. The Congress party itself was a ''coalition'' of different interests and social strata and groups, giving rise to the term ''Congress system''. The rise of regional parties and the decline of the Congress party led to the emergence of coalition governments.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40c' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-of-coalition-governments' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
