UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-510","language":"English","title":"Regional Aspirations","topic_slug":"regional-aspirations","definition":"Regional aspirations are usually expressed in the language of the region and addressed to the local population or the rulers. These aspirations are often expressed outside the framework of the Indian Union and involve long struggles and aggressive and armed assertions by the people. The Indian state has responded to these tensions and challenges through a process of dialogue that aims to settle contentious issues within the constitutional framework.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'regional-aspirations' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-511","language":"English","title":"Region and the Nation","topic_slug":"region-and-the-nation","definition":"The 1980s may be seen as a period of rising regional aspirations for autonomy, often outside the framework of the Indian Union. These movements frequently involved armed assertions by the people, their repression by the government, and a collapse of the political and electoral processes. The accords were reached after a process of dialogue that aimed to settle contentious issues within the constitutional framework.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'region-and-the-nation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-512","language":"English","title":"Indian Approach","topic_slug":"indian-approach","definition":"The Indian nation shall not deny the rights of different regions and linguistic groups to retain their own culture. Indian nationalism sought to balance the principles of unity and diversity, and the nation would not mean the negation of the region. India adopted a democratic approach to the question of diversity, allowing the political expressions of regional aspirations and not looking upon them as anti-national.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'indian-approach' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-513","language":"English","title":"Politics in India since Independence","topic_slug":"politics-in-india-since-independence","definition":"The challenge of diversity was met by redrawing the internal boundaries of the country, with the creation of new states such as Punjab, Haryana, Chhattisgarh, Uttarakhand, and Jharkhand. However, this did not lead to the resolution of all problems and for all times, with new challenges coming up in states such as Punjab, Assam, and Mizoram.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'politics-in-india-since-independence' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-514","language":"English","title":"Areas of Tension","topic_slug":"areas-of-tension","definition":"The issue of Jammu and Kashmir came up soon after Independence, with a conflict between India and Pakistan and a question of the political aspirations of the people of Kashmir valley. In some parts of the north-east, there was no consensus about being a part of India, with Nagaland and Mizoram witnessing strong movements demanding separation from India. Mass agitations were also held in many parts for the formation of linguistic states, with today''s Andhra Pradesh, Karnataka, Maharashtra, and Gujarat being among the regions affected.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'areas-of-tension' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-515","language":"English","title":"Regional Aspirations in Jammu and Kashmir","topic_slug":"regional-aspirations-in-jammu-and-kashmir","definition":"Jammu and Kashmir had a special status under Article 370 of the Indian Constitution, but experienced violence, cross-border terrorism, and political instability with internal and external ramifications. The state comprises three social and political regions – Jammu, Kashmir, and Ladakh – with different cultural and linguistic identities.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'regional-aspirations-in-jammu-and-kashmir' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-516","language":"English","title":"Roots of the Problem in Jammu and Kashmir","topic_slug":"roots-of-the-problem-in-jammu-and-kashmir","definition":"Before 1947, Jammu and Kashmir was a Princely State, with its ruler, Maharaja Hari Singh, not wanting to merge with either India or Pakistan but to have an independent status for his state. The Pakistani leaders thought that the Kashmir region ''belonged'' to Pakistan, since the majority population of the state was Muslim, but this is not how the people of the state themselves saw it – they thought of themselves as Kashmiris above all.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'roots-of-the-problem-in-jammu-and-kashmir' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-517","language":"English","title":"Dravidian Movement","topic_slug":"dravidian-movement","definition":"The Dravidian movement was one of India''s most effective regional movements, with a popular slogan ''Vadakku Vaazhgiradhu' || char(59) || ' Therkku Thaeikiradhu'' (The north thrives even as the south decays). The movement used democratic means like public debates and the electoral platform to achieve its ends, with the Dravidar Kazhagam (DK) under the leadership of Tamil social reformer E.V. Ramasami ''Periyar'' being a key organisation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dravidian-movement' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87832c1a19d2142de40b-en-518","language":"English","title":"The DMK and its Legacy","topic_slug":"the-dmk-and-its-legacy","definition":"The DMK made its entry into politics with a three-pronged agitation in 1953-54, demanding the restoration of the original name of Kallakudi railway station, giving Tamil cultural history greater importance in school curricula, and agitating against making Hindi the country''s official language. The success of the anti-Hindi agitation of 1965 added to the DMK''s popularity, and sustained political agitations brought the DMK to power in the Assembly elections of 1967.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87832c1a19d2142de40b' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-dmk-and-its-legacy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a90409b-3488-47ef-b443-e4c2f1bdf469-en-519","language":"English","title":"Course overview","topic_slug":"course-overview","definition":"This multidisciplinary course examines Assam’s transition into the modern era. It explores the meanings and features of modernity in colonial Assam, and traces the origin and growth of modern ideas and institutions. The course introduces people and organizations that shaped Assamese society, while considering how women and tribal communities participated in and benefited from social change.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a90409b-3488-47ef-b443-e4c2f1bdf469' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'course-overview' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a90409b-3488-47ef-b443-e4c2f1bdf469-en-520","language":"English","title":"Learning objectives","topic_slug":"learning-objectives","definition":"Understand the historical transition of Assam into the modern era, including the context and aspects of modernity in colonial Assam. - Identify the institutions and personalities that helped shape modern Assamese society. - Examine how emancipatory efforts affected marginalized groups, including women and tribal communities.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a90409b-3488-47ef-b443-e4c2f1bdf469' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'learning-objectives' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a90409b-3488-47ef-b443-e4c2f1bdf469-en-521","language":"English","title":"Course outcomes","topic_slug":"course-outcomes","definition":"By the end of the course, students should be able to: - Explain the context and historical processes behind Assam’s transition to the modern era. - Describe key figures and institutions that influenced Assam’s social, cultural and political life. - Discuss historical processes that supported the empowerment of women and tribal communities.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a90409b-3488-47ef-b443-e4c2f1bdf469' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'course-outcomes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a90409b-3488-47ef-b443-e4c2f1bdf469-en-522","language":"English","title":"Assessment reference in the supplied 2024 paper","topic_slug":"assessment-reference-in-the-supplied-2024-paper","definition":"The supplied 2024 paper lists 45 marks and 2½ hours , with this structure: - 1-mark questions: answer five (5 marks). - 2-mark questions: answer any five (10 marks). - 5-mark questions: write on any four (20 marks). - 10-mark questions: answer any one (10 marks). This is the pattern printed on the supplied 2024 paper' || char(59) || ' confirm the current examination pattern with the official syllabus or institution.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a90409b-3488-47ef-b443-e4c2f1bdf469' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'assessment-reference-in-the-supplied-2024-paper' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-523","language":"English","title":"Anandaram Dhekial Phukan","topic_slug":"anandaram-dhekial-phukan","definition":"Historical Context & The Language Crisis: Following the British annexation of Assam (Treaty of Yandaboo, 1826), the colonial administration imposed Bengali as the official language of courts and schools in 1836 under the erroneous assumption that Assamese was merely a vulgar dialect of Bengali. Anandaram Dhekial Phukan emerged as the pioneer intellectual who spearheaded the resistance against this linguistic subjugation. Literary Works & Textbooks: Asamiya Lorar Mitra (The Assamese Boy’s Companion, 1849): An Assamese-language textbook for young readers. Its publication predates the reinstatement of Assamese in schools and courts in 1873. A Few Remarks on the Assamese Language and on Vernacular Education in Assam (1855): A definitive analytical treatise printed at the American Baptist Mission Press in Sibsagar, arguing for Assamese as an independent language and for vernacular education' || char(59) || ' his specific 19th-century etymological framing should be read in context rather than treated as present-day linguistic consensus. Representation to A.J.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'anandaram-dhekial-phukan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-524","language":"English","title":"Lakshminath Bezbaruah","topic_slug":"lakshminath-bezbaruah","definition":"The Jonaki Era & The Romantic Awakening: In 1889, along with Chandra Kumar Agarwala and Hemchandra Goswami, Bezbaruah founded the literary journal Jonaki under the aegis of the Asamiya Bhasa Unnati Sadhini Sabha (ABUSS) in Calcutta. This marked the advent of Romanticism (Romantisiwad) in Assamese literature, breaking away from medieval devotional models to embrace individual emotion, patriotism, and folklore. The Rasaraj Identity & Satirical Persona: Honored with the epithet \"Rasaraj\" (The King of Humor) by the Asom Sahitya Sabha in 1931 for his masterly use of humor and wit to provoke social reform. Adopted the pseudonym \"Kripabar Barbarua\" to author satirical essays including Kripabar Barbaruar Kakator Topola and Kripabar Barbaruar Obhotoni. Through Kripabar’s eccentric musings, Bezbaruah ridiculed Assamese inertia, blind imitation of Western manners, and orthodox social taboos.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'lakshminath-bezbaruah' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-525","language":"English","title":"Dr. Banikanta Kakati","topic_slug":"dr-banikanta-kakati","definition":"Scientific Philology & Doctoral Dissertation: Submitted his doctoral thesis to Calcutta University in 1935, subsequently published as Assamese: Its Formation and Development (1941). Using comparative Indo-Aryan philology, Kakati documented Assamese as an independent language with a historical development distinct from Bengali, tracing it to Eastern Indo-Aryan sources. Key Published Books: Assamese: Its Formation and Development (Linguistic treatise). Purani Asamiya Sahitya (1940): Pioneered modern literary criticism, evaluating pre-colonial Vaishnava texts with aesthetic standards rather than blind devotion. The Mother Goddess Kamakhya (1948): An anthropological study detailing the fusion of Aryan and non-Aryan/Austric/Tibeto-Burman religious cults in Assam. Kalita Jatir Itibritta: An ethnological investigation into the social origins and mobility of the Kalita community in the Brahmaputra Valley. Sahitya Aru Prem: A philosophical critique of romantic love and ethical aestheticism in world literature.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dr-banikanta-kakati' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-526","language":"English","title":"Jyoti Prasad Agarwala","topic_slug":"jyoti-prasad-agarwala","definition":"The Title ''Rupkonwar'' & Philosophy of Sundarar Pujari: Conferred the title \"Rupkonwar\" (Prince of Beauty) by contemporary cultural circles and literary figures in recognition of his artistic pursuit of ideal beauty. As the \"Sundarar Pujari\" (Worshipper of Beauty), he defined beauty not as escapism, but as a revolutionary force (Biplobi Saundaryabodh) capable of demolishing social injustice, inequality, and colonial oppression. Pioneering Dramatic Literature: Sonit Konwari (1925): Modernized mythological theatre by integrating traditional folk rhythms with structured dialogue. Karengar Ligiri (The Maid of the Palace, 1930): A tragedy exploring individual psychological freedom against feudal societal conventions. Rupalim (1938): Set against a tribal backdrop, analyzing love, political tyranny, and moral sacrifice. Labhita (1948): A realistic drama capturing the transformation of a rural Assamese village girl into a political activist during the 1942 Quit India Movement and the INA campaign.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'jyoti-prasad-agarwala' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-527","language":"English","title":"Bishnu Prasad Rabha","topic_slug":"bishnu-prasad-rabha","definition":"The Title ''Kalaguru'': The title \"Kalaguru\" (Master of Arts) was conferred on him by Dr. Sarvepalli Radhakrishnan at Banaras Hindu University following Rabha''s classical performance of the Nataraja Tandava dance. Cultural Synthesis & Tribal Integration: Rejected narrow chauvinism, asserting that Greater Assamese culture (Bor Asom) is fundamentally an amalgamation of diverse tribal streams (Bodo, Kachari, Mishing, Karbi, Rabha) and Sanskritic heritage. Documented indigenous musical scales, dances, and folklore in seminal works such as Asamiya Kristir Chamu Abhas (A Brief Overview of Assamese Culture). Revolutionary Politics: An active member of the Revolutionary Communist Party of India (RCPI), he went underground in the late 1940s, mobilizing peasant movements (Kisan Sabha) across lower Assam to resist feudal land systems. Imprisoned repeatedly, he utilized his creative arts as instruments of proletarian class struggle and tribal emancipation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bishnu-prasad-rabha' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-586be1bf-5260-44d1-b535-c3df816a5ad2-en-528","language":"English","title":"Dr. Bhupen Hazarika","topic_slug":"dr-bhupen-hazarika","definition":"Lyrical Themes & Universal Humanism: Integrated the philosophies of Paul Robeson, folk realism, and humanitarian socialism into Assamese mass music. Landmark compositions: Bistirno Parore (inspired in part by Paul Robeson''s Ol'' Man River, and using the Brahmaputra as a witness to human suffering and social injustice), Manuhe Manuhor Babe (championing universal empathy), and Dola He Dola (depicting the suffering of palanquin bearers). Bridge of Ethnic Unity in the Northeast: Used his compositions to celebrate the folk traditions of the hills and plains, writing songs dedicated to the Khasi, Garo, Naga, Arunachal, and Mishing communities, serving as an emotional bridge during periods of regional ethnic friction. Chronology of National Awards & Honors: Padma Shri (1977). Sangeet Natak Akademi Award (1987). Dadasaheb Phalke Award (1992): India''s highest award in cinema, acknowledging his contribution to Assamese and Indian music/films. Padma Bhushan (2001). Asam Ratna (2009). Padma Vibhushan (2012, posthumously).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '586be1bf-5260-44d1-b535-c3df816a5ad2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dr-bhupen-hazarika' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-18da023f-768c-4647-ad99-65e97a707a40-en-529","language":"English","title":"Anandaram Dhekial Phukan","topic_slug":"anandaram-dhekial-phukan","definition":"Historical Context & The Language Crisis: Following the British annexation of Assam (Treaty of Yandaboo, 1826), the colonial administration imposed Bengali as the official language of courts and schools in 1836 under the erroneous assumption that Assamese was merely a vulgar dialect of Bengali. Anandaram Dhekial Phukan emerged as the pioneer intellectual who spearheaded the resistance against this linguistic subjugation. Literary Works & Textbooks: Asamiya Lorar Mitra (The Assamese Boy’s Companion, 1849): Written to provide native vernacular reading material for young students, fulfilling the colonial requirement of having standardized local textbooks before Assamese could be reinstated in classrooms.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '18da023f-768c-4647-ad99-65e97a707a40' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'anandaram-dhekial-phukan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
