UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-18da023f-768c-4647-ad99-65e97a707a40-en-534","language":"English","title":"Dr. Bhupen Hazarika","topic_slug":"dr-bhupen-hazarika","definition":"Lyrical Themes & Universal Humanism: Integrated the philosophies of Paul Robeson, folk realism, and humanitarian socialism into Assamese mass music. Landmark compositions: Bistirno Parore (an adaptation of Robeson''s Ol'' Man River, castigating the moral silence of the Brahmaputra), Manuhe Manuhor Babe (championing universal empathy), and Dola He Dola (depicting the suffering of palanquin bearers). Bridge of Ethnic Unity in the Northeast: Used his compositions to celebrate the folk traditions of the hills and plains, writing songs dedicated to the Khasi, Garo, Naga, Arunachal, and Mishing communities, serving as an emotional bridge during periods of regional ethnic friction. Chronology of National Awards & Honors: Padma Shri (1977). Sangeet Natak Akademi Award (1987). Dadasaheb Phalke Award (1992): India''s highest award in cinema, acknowledging his contribution to Assamese and Indian music/films. Padma Bhushan (2001). Asam Ratna (2009). Padma Vibhushan (2012, posthumously). Bharat Ratna (2019, posthumously): India''s highest civilian honor.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '18da023f-768c-4647-ad99-65e97a707a40' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'dr-bhupen-hazarika' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
